/* Triple Triad cards: the catalog of Final Fantasy XIV's cards (src/tt/tt_catalog.c, generated by tools/tt/gen_catalog.py
 * from tools/tt/cards.json, which tools/tt/fetch_cards.py reads from xivapi), the rules (Final Fantasy VIII's, from the
 * PS1 game's own code, and a few of XIV's), the trade rules, and the packs. */
#ifndef MOEMON_TT_H
#define MOEMON_TT_H
#include <stddef.h>
#include <stdint.h>
#include "tt/card_ids.h"   /* TT_CARD_MAX: the highest card id (ids are XIV's own and never move) */

#define TT_HAND 5
#define TT_CELLS 9
#define TT_RANK_A 10      /* the card's "A" */
#define TT_MAX_STARS 5

/* Card types (XIV's): the Ascension, Descension and Elemental rules look at them */
enum { TT_TYPE_NONE, TT_TYPE_PRIMAL, TT_TYPE_SCION, TT_TYPE_SOCIETY, TT_TYPE_GARLEAN, TT_TYPE_COUNT };
/* Sides, clockwise from the top: the facing side is (d + 2) & 3 */
enum { TT_UP, TT_RIGHT, TT_DOWN, TT_LEFT };

struct TtCard
{
    const char *name, *text;
    uint8_t side[4];        /* TT_UP.. : 1-10 (10 = A) */
    uint8_t stars, type;
    uint16_t sale;          /* what a spare copy fetches (XIV's sale value) */
    uint16_t order;         /* the card's number in XIV's list */
};
extern const struct TtCard gTtCards[TT_CARD_MAX + 1];   /* [0] and missing ids: name NULL */
static inline const struct TtCard *Tt_Card(unsigned id)
{
    return id && id <= TT_CARD_MAX && gTtCards[id].name ? &gTtCards[id] : NULL;
}

/* The rules. The first eight are Final Fantasy VIII's (the regions of HOENN spread them); the rest XIV's. */
enum
{
    TT_RULE_OPEN,          /* both hands face up */
    TT_RULE_SAME,          /* two or more sides equal to their neighbors' take them (and combo) */
    TT_RULE_PLUS,          /* two or more side + neighbor sums alike take them (and combo) */
    TT_RULE_RANDOM,        /* the hand is five cards dealt at random from the collection */
    TT_RULE_SUDDEN_DEATH,  /* a draw is played again with the cards each side ended with */
    TT_RULE_SAME_WALL,     /* an A against the board's edge counts for SAME */
    TT_RULE_ELEMENTAL,     /* some squares carry a type: +1 to a card of that type, -1 to any other */
    TT_RULE_THREE_OPEN,    /* three cards of each hand face up */
    TT_RULE_REVERSE,       /* the lower number takes */
    TT_RULE_FALLEN_ACE,    /* a 1 takes an A */
    TT_RULE_ASCENSION,     /* +1 to a typed card for each card of its type on the board */
    TT_RULE_DESCENSION,    /* -1 likewise */
    TT_RULE_ORDER,         /* cards are played in the hand's order */
    TT_RULE_CHAOS,         /* the card to play is chosen at random */
    TT_RULE_SWAP,          /* one card of each hand changes sides at the start */
    TT_RULE_COUNT
};
#define TT_FF8_RULES 7     /* OPEN .. ELEMENTAL: the rules the regions start with */
#define TT_RULE_BIT(r) (1u << (r))
/* What the winner takes (only ever the player: losing never costs a card) */
enum { TT_TRADE_ONE, TT_TRADE_DIFF, TT_TRADE_DIRECT, TT_TRADE_ALL, TT_TRADE_COUNT };

const char *Tt_RuleName(unsigned rule);
const char *Tt_RuleHelp(unsigned rule);
const char *Tt_TradeName(unsigned trade);
const char *Tt_TradeHelp(unsigned trade);
const char *Tt_TypeName(unsigned type);
/* Good or bad for whoever brings the stronger hand: +1 helps skill (OPEN, SAME...), -1 luck (RANDOM, CHAOS) */
int Tt_RuleLean(unsigned rule);

/* Decks: five different cards; at most two of four stars or more, and only one of five */
#define TT_DECKS 6
#define TT_DECK_NAME 16
int Tt_DeckValid(const uint16_t *cards, char *reason, size_t reasonLen);
/* Could this card join these (the other four slots)? 0 no (reason) */
int Tt_DeckFits(const uint16_t *cards, unsigned slot, unsigned id, char *reason, size_t reasonLen);

/* Packs, by stars: BRONZE 1, SILVER 2, GOLD 3 are sold; MYTHRIL 4 and IMPERIAL 5 are only won */
#define TT_PACK_TYPES 5
#define TT_PACK_SIZE 3
#define TT_PACK_SOLD 3     /* the shops sell the first three */
const char *Tt_PackName(unsigned pack);
unsigned Tt_PackPrice(unsigned pack);   /* 0: not for sale */
unsigned Tt_SinglePrice(unsigned id);   /* the shops' price for a single */
#endif
